function traceCapacity(capacity, deltas) {
  if (!Number.isSafeInteger(capacity) || capacity < 0) {
    throw new TypeError('capacity must be a non-negative safe integer');
  }
  if (!Array.isArray(deltas) || deltas.some(delta => !Number.isSafeInteger(delta))) {
    throw new TypeError('deltas must be an array of safe integers');
  }

  let load = 0;
  const steps = deltas.map((delta, index) => {
    const before = load;
    const candidate = before + delta;
    const accepted = Number.isSafeInteger(candidate) && candidate > 0 && candidate <= capacity;
    if (accepted) load = candidate;
    return { attempt: index + 1, before, delta, after: load, accepted };
  });
  return { finalLoad: load, steps };
}

module.exports = { traceCapacity };

