'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['traceCapacity']);
const { traceCapacity } = api;

assert.deepEqual(traceCapacity(0, []), { finalLoad: 0, steps: [] });
assert.deepEqual(traceCapacity(0, [0, 1, -1]), {
  finalLoad: 0,
  steps: [
    { attempt: 1, before: 0, delta: 0, after: 0, accepted: true },
    { attempt: 2, before: 0, delta: 1, after: 0, accepted: false },
    { attempt: 3, before: 0, delta: -1, after: 0, accepted: false }
  ]
});

const deltas = Object.freeze([3, 2, 1, -5, -1, 5]);
const result = traceCapacity(5, deltas);
assert.deepEqual(result, {
  finalLoad: 5,
  steps: [
    { attempt: 1, before: 0, delta: 3, after: 3, accepted: true },
    { attempt: 2, before: 3, delta: 2, after: 5, accepted: true },
    { attempt: 3, before: 5, delta: 1, after: 5, accepted: false },
    { attempt: 4, before: 5, delta: -5, after: 0, accepted: true },
    { attempt: 5, before: 0, delta: -1, after: 0, accepted: false },
    { attempt: 6, before: 0, delta: 5, after: 5, accepted: true }
  ]
});
assert.notStrictEqual(result.steps[0], result.steps[1]);
assert.notStrictEqual(result.steps, deltas);

assert.deepEqual(traceCapacity(Number.MAX_SAFE_INTEGER, [Number.MAX_SAFE_INTEGER, 1]), {
  finalLoad: Number.MAX_SAFE_INTEGER,
  steps: [
    { attempt: 1, before: 0, delta: Number.MAX_SAFE_INTEGER, after: Number.MAX_SAFE_INTEGER, accepted: true },
    { attempt: 2, before: Number.MAX_SAFE_INTEGER, delta: 1, after: Number.MAX_SAFE_INTEGER, accepted: false }
  ]
});

for (const capacity of [-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '5']) {
  assert.throws(() => traceCapacity(capacity, []), TypeError);
}
assert.throws(() => traceCapacity(5, {}), TypeError);
for (const delta of [1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '1']) {
  assert.throws(() => traceCapacity(5, [delta]), TypeError);
}

